\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(condition boolean,message text) returns void language plpgsql as $$ begin if condition is distinct from true then raise exception 'ASSERT: %',message; end if; end $$;
insert into auth.users(id) select ('90000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid from generate_series(1,3) i;
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000001',true);
select public.app_action('create_team','{"name":"数据边界","timezone":"Asia/Shanghai"}');
create temp table context as select app.team_for(auth.uid()) team_id,(public.app_action('create_invite')->>'token') token;
select public.app_action('save_plan','{"title":"学习","category":"exercise","weekdays":[1,2,3,4,5,6,7],"start_time":"00:00","deadline":"23:59","visibility":"team"}');
select public.app_action('save_plan','{"title":"私密饮食","category":"food","weekdays":[1,2,3,4,5,6,7],"start_time":"00:00","deadline":"23:59","visibility":"private"}');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000002',true);
select public.app_action('join_team',jsonb_build_object('token',token)) from context;
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000003',true);
select public.app_action('join_team',jsonb_build_object('token',token)) from context;
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000001',true);
do $$ begin
 perform public.app_action('save_plan',jsonb_build_object('id',(select id from public.plans where title='学习'),'title','bad','category','study','weekdays',jsonb_build_array(8),'start_time','00:00','deadline','23:59'));
 raise exception 'accepted invalid pending config';
 exception when raise_exception then if sqlerrm<>'请核对计划名称、频率、状态与时段' then raise; end if;
end $$;
insert into public.media(id,user_id,team_id,batch_id,path,source,captured_at,local_date,phash)
select ('91000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,auth.uid(),team_id,'92000000-0000-4000-8000-000000000001','test/'||i||'.jpg','camera',now(),(now() at time zone 'Asia/Shanghai')::date,'hash-new-'||i from context cross join generate_series(1,2) i;
select public.app_action('submit_checkin','{"media_ids":["91000000-0000-4000-8000-000000000001","91000000-0000-4000-8000-000000000002"],"idempotency_key":"all-batch-test"}');
create temp table original as select id from public.checkins;
select pg_temp.assert_true((select visibility='private' and status='stamped' from public.checkins),'ALL stamped with privacy until classification');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=0 from public.media),'unclassified batch not exposed to teammate');
reset role;
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000001',true);
select public.app_action('edit_memo',jsonb_build_object('checkin_id',(select id from original),'summary','私密学习密码只留给自己','fields','[{"key":"duration_seconds","label":"运动时长","value":600,"source":"manual"}]'::jsonb));
create temp table claimed as select * from public.claim_jobs('ai',10) where payload->>'version'='2';
create temp table result as select jsonb_build_object('version',2,'job_id',id,'lease_token',lease_token,
 'assignments',jsonb_build_array(jsonb_build_object('photo_id','91000000-0000-4000-8000-000000000001','plan_id',(select id from public.plans where title='学习'),'confidence',0.95),jsonb_build_object('photo_id','91000000-0000-4000-8000-000000000002','plan_id',(select id from public.plans where title='私密饮食'),'confidence',0.9)),
 'groups',jsonb_build_array(jsonb_build_object('plan_id',(select id from public.plans where title='学习'),'photo_ids',jsonb_build_array('91000000-0000-4000-8000-000000000001'),'summary','今天读了一页','fields','[]'::jsonb),jsonb_build_object('plan_id',(select id from public.plans where title='私密饮食'),'photo_ids',jsonb_build_array('91000000-0000-4000-8000-000000000002'),'summary','私人饮食记录','fields','[]'::jsonb))) body from claimed;
select pg_temp.assert_true(not (public.apply_ai_result((select id from original),(select body||jsonb_build_object('lease_token',gen_random_uuid()) from result))->>'applied')::boolean,'stale lease cannot commit AI');
select public.apply_ai_result((select id from original),(select body from result));
select pg_temp.assert_true((select count(*)=2 from public.checkins),'mixed photo batch split by plan');
select pg_temp.assert_true((select count(*)=2 from public.checkins where version>=2 and memo_status='ready' and not classification_pending and summary not like '%私密学习密码%'),'batch note not copied to classified cards');
select pg_temp.assert_true((select summary='私密学习密码只留给自己' from public.batch_field_drafts),'private summary preserved as one draft');
select pg_temp.assert_true((select sum(jsonb_array_length(fields))=0 from public.checkins),'ambiguous manual duration not duplicated into groups');
select pg_temp.assert_true((select count(*)=1 from public.batch_field_drafts),'manual fields preserved exactly once');
select public.apply_ai_result((select id from original),(select body from result));
select pg_temp.assert_true((select count(*)=2 from public.checkins),'AI replay cannot split twice');
select pg_temp.assert_true(app.streak(auth.uid())=1,'one day counted once across plans');
select pg_temp.assert_true(app.team_streak((select team_id from context))=1,'team streak derived from public due plans');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=1 from public.media),'private classified photo remains private');
select pg_temp.assert_true((select count(*)=0 from public.batch_field_drafts),'unassigned manual fields private to owner');
select pg_temp.assert_true(public.bootstrap()::text not like '%私密学习密码%','private batch note absent from teammate snapshot');
reset role;
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000001',true);
select public.app_action('assign_batch_fields',jsonb_build_object('checkin_id',(select id from original),'target_checkin_id',(select id from public.checkins where visibility='private')));
select pg_temp.assert_true((select sum(jsonb_array_length(fields))=1 from public.checkins),'user assigns manual fields to exactly one group');
select pg_temp.assert_true((select count(*)=0 from public.batch_field_drafts),'field assignment consumes draft');
select pg_temp.assert_true((select summary='私密学习密码只留给自己' from public.checkins where visibility='private'),'private summary assigned only to chosen card');
select app.build_report(auth.uid(),date_trunc('week',now() at time zone 'Asia/Shanghai')::date,'Asia/Shanghai');
select public.app_action('share_report',jsonb_build_object('report_id',(select id from public.reports),'method','image'));
select pg_temp.assert_true((select not shared and image_shared from public.reports),'image export does not silently share to team');
select public.app_action('share_report',jsonb_build_object('report_id',(select id from public.reports),'method','feed'));
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=0 from public.reports),'teammate cannot read raw private report metrics');
select pg_temp.assert_true(public.bootstrap()::text not like '%私人饮食记录%' and public.bootstrap()::text not like '%私密饮食%','shared report redacts private plans and memos');
reset role;
select public.app_action('interact_report',jsonb_build_object('report_id',(select id from public.reports),'kind','comment','content','下周继续')); 
select public.app_action('interact_report',jsonb_build_object('report_id',(select id from public.reports),'kind','like'));
select pg_temp.assert_true((select count(*)=2 from public.report_interactions),'report supports comment and like');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true(not app.validate_fields('[{"key":"duration_seconds","label":"时长","value":120,"source":"ai"}]','exercise'),'AI cannot invent sourced duration');
select pg_temp.assert_true(not app.validate_fields('[{"key":"calories","label":"热量","value":{"min":600,"max":400,"estimated":true},"source":"manual"}]','food'),'invalid calorie range rejected');
select public.app_action('pause_week','{"paused":true}');
select pg_temp.assert_true(app.day_outcome(auth.uid(),(now() at time zone 'Asia/Shanghai')::date)=-1,'paused week is rest');
select pg_temp.assert_true(public.bootstrap()->'profile'->'paused_week'='true'::jsonb,'paused week wire is boolean');
select public.app_action('pause_week','{"paused":false}');
select pg_temp.assert_true(app.day_outcome(auth.uid(),(now() at time zone 'Asia/Shanghai')::date)=1,'unpause restores due day');
select pg_temp.assert_true(not has_function_privilege('authenticated','public.app_action_core(text,jsonb)','execute'),'wrapper core inaccessible');
select pg_temp.assert_true(not has_function_privilege('authenticated','public.apply_report_result(uuid,jsonb)','execute'),'report writer inaccessible');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000002',true);
select public.app_action('interact',jsonb_build_object('checkin_id',(select id from public.checkins where visibility='team'),'kind','challenge','content','请补充一页'));
select pg_temp.assert_true((select status='stamped' from public.checkins where visibility='team'),'1 of 3 stays stamped');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000003',true);
select public.app_action('interact',jsonb_build_object('checkin_id',(select id from public.checkins where visibility='team'),'kind','challenge','content','请补充来源'));
select pg_temp.assert_true((select status='redo_required' and frozen_user_streak=1 from public.checkins where visibility='team'),'2 of 3 freezes original streak');
select pg_temp.assert_true(app.streak('90000000-0000-4000-8000-000000000001')=1,'challenge does not deduct existing streak');
select public.app_action('register_device','{"platform":"ios","provider":"apns","token":"test-owned-token"}');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000001',true);
select public.app_action('unregister_device','{"token":"test-owned-token"}');
select pg_temp.assert_true((select count(*)=1 from public.devices),'cannot unregister another user device');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000003',true);
select public.app_action('unregister_device','{"token":"test-owned-token"}');
select public.app_action('unregister_device','{"token":"test-owned-token"}');
select pg_temp.assert_true((select count(*)=0 from public.devices),'device unregister own token is idempotent');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000001',true);
update public.media set analysis_path=path||'.analysis.jpg';
select public.app_action('delete_photo','{"photo_id":"91000000-0000-4000-8000-000000000001"}');
select public.app_action('delete_photo','{"photo_id":"91000000-0000-4000-8000-000000000001"}');
select pg_temp.assert_true((select count(*)=1 from public.jobs where kind='cleanup'),'delete queues one persistent task');
select pg_temp.assert_true((select jsonb_array_length(payload->'paths')=2 from public.jobs where kind='cleanup'),'cleanup contains original and analysis paths');
select pg_temp.assert_true(public.bootstrap()::text like '%"cleanup_status": "pending"%','pending photo cleanup visible to owner after refresh');
create temp table cleanup_claim as select * from public.claim_jobs('cleanup',1);
select pg_temp.assert_true(not public.complete_media_cleanup('91000000-0000-4000-8000-000000000001',(select id from cleanup_claim),gen_random_uuid()),'cleanup requires valid lease');
select public.complete_media_cleanup('91000000-0000-4000-8000-000000000001',id,lease_token) from cleanup_claim;
select pg_temp.assert_true((select cleanup_status='done' from public.media where id='91000000-0000-4000-8000-000000000001'),'cleanup receipt recorded');

-- A note entered during ALL submission is private even without edit_memo.
insert into public.media(id,user_id,team_id,batch_id,path,source,captured_at,local_date,phash)
select '91000000-0000-4000-8000-000000000003',auth.uid(),team_id,'92000000-0000-4000-8000-000000000002','test/unedited.jpg','camera',now(),(now() at time zone 'Asia/Shanghai')::date,'hash-unedited-note' from context;
create temp table unedited_note as select (public.app_action('submit_checkin','{"media_ids":["91000000-0000-4000-8000-000000000003"],"idempotency_key":"unedited-all-note","note":"未编辑的私人批次说明"}')->'checkin_ids'->>0)::uuid id;
select pg_temp.assert_true((select not user_edited from public.checkins where id=(select id from unedited_note)),'submission note does not require manual edit marker');
create temp table unedited_claim as select * from public.claim_jobs('ai',10) where payload->>'checkin_id'=(select id::text from unedited_note);
select public.apply_ai_result((select id from unedited_note),jsonb_build_object('version',1,'job_id',id,'lease_token',lease_token,
 'assignments',jsonb_build_array(jsonb_build_object('photo_id','91000000-0000-4000-8000-000000000003','plan_id',(select id from public.plans where title='学习'),'confidence',0.95)),
 'groups',jsonb_build_array(jsonb_build_object('plan_id',(select id from public.plans where title='学习'),'photo_ids',jsonb_build_array('91000000-0000-4000-8000-000000000003'),'summary','照片中的活动已记录','fields','[]'::jsonb)))) from unedited_claim;
select pg_temp.assert_true((select summary='未编辑的私人批次说明' and fields='[]'::jsonb from public.batch_field_drafts where checkin_id=(select id from unedited_note)),'unedited ALL note preserved in private draft even for one group');
select pg_temp.assert_true((select summary='照片中的活动已记录' and visibility='team' from public.checkins where id=(select id from unedited_note)),'public classified card has only photo summary');
select pg_temp.assert_true(public.bootstrap()::text like '%未编辑的私人批次说明%','owner snapshot contains unassigned submission note');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select pg_temp.assert_true(public.bootstrap()::text not like '%未编辑的私人批次说明%','unedited ALL note absent from teammate snapshot');
reset role;
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000001',true);
select public.app_action('assign_batch_fields',jsonb_build_object('checkin_id',id,'target_checkin_id',id)) from unedited_note;
select pg_temp.assert_true((select not exists(select 1 from public.batch_field_drafts where checkin_id=id) from unedited_note),'summary-only assignment consumes draft');
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select pg_temp.assert_true(public.bootstrap()::text like '%未编辑的私人批次说明%','explicit public-card assignment publishes submission note');
reset role;
rollback;
\echo 'PASS hardening: lease CAS, batch splitting, streaks, report privacy and interactions'
